export declare const BUBBLE_CONFERENCE_SVC = "BubbleConferenceService";
/**
 * This service manages web conferences in Rainbow (web conferences that take place in bubbles).
 * Any Rainbow user in the bubble can take part of the conference (the maximum number of participants is based on the licence of the organiser of the conference)
 * In each conference, there's only one "organizer" (the user that has started the conference), but every administrator in the bubble is allowed to make additional actions on all other participants (like drop, mute, etc)
 * Only the organizer of the conference can stop the conference, or delegate it to another user.
 *
 * By default, the web conference service is going to use a web conference helper service that will manage
 * an automatic subscription to all available videos, the management of the dynamic feed.
 * This service configuration can be managed by setHelperServiceConfiguration API
 *
 * NB !! The CPU and bandwidth consumption should/can be managed via additionnal APIs that can be used so that the application is adapted;
 * As all incoming videos are available in 3 sublayers (high HD, medium VGA and low QVGA) the user can change the sublayer he wants to receive from the server (managed by the Method updateParticipant)
 * In addition, some session can be put on hold / unhold so that the user can "pause" all incoming videos that are not needed at the moment (managed by putRemoteVideoSessionOnHold)
 */
export interface BubbleConferenceService {
    /**
     * Subscribe to updates from the service (all events are of RBEvent type {name: string, data:any});
     * @param handler - The call-back function that will be subscribed to the RxJS subject
     * @param eventNames - array of event to listen
     * @returns Returns RxJS Subscription
     */
    subscribe(handler: any, eventNames?: string | string[]): Subscription;
    /**
     * Create a web conference in the given bubble
     * @param bubble - The bubble associated with this conference
     */
    startConference(bubble: Bubble): Promise<BubbleConference>;
    /**
     * Get bubble web conference if exists
     * @param bubble - The bubble associated with this conference
     */
    getConference(bubble: Bubble): BubbleConference | undefined;
    /**
     * Add media (video or sharing) to an existing web conference
     * @internal
     * @param webConference - the WebConference object where we want to add the media
     * @param mediaType - the type of the media to be added. Accepted values are 'video' or 'sharing';
     * @param existingStream - if we want to use an already existing stream
     * @param getAudioForSharing - if we want to add audio from system to sharing
     */
    addMediaToWebConference(webConference: BubbleConference, mediaType: BubbleConferenceMedia, existingStream?: MediaStream, getAudioForSharing?: boolean): Promise<void>;
    /**
     * Remove Media from the current web conference. It could be either 'video' or 'sharing'
     * @internal
     * @param webConference - The Web conference
     * @param mediaType - the media to be removed 'video' or 'sharing'
     */
    removeMediaFromWebConference(webConference: BubbleConference, mediaType: BubbleConferenceMedia): void;
    /**
     *  Update a conference participant (ourself, or any other participant if the user is a moderator of the conference)
     * @internal
     * @param webConference -The Web Conference
     * @param participantId -ID of participant to update
     * @param option -update data ( could be on of: mute, unmute, hold, retrieve, plug, unplug, update);
     * With 'update' option we can :
     * - Update media bandwidth as publisher. Two parameters must be present: media and bitRate
     * - Update substream level as subscriber. One parameter must be present: subStreamLevel. Parameter publisherId is optional.
     * @param media - type of media to be updated (video/sharing)
     * @param bitRate - the max bitrate to be set (0 is unlimited)
     * @param subStreamLevel - set new sub-stream level. Only available for publishers and in simulcast mode (0 - low, 1 - medium, 2 - high)
     * @param publisherId - the publisher id related to the update
     * @returns a promise that resolve when particpant state is updated
     */
    updateParticipant(webConference: BubbleConference, participantId: string, option: string, media?: string, bitRate?: string, subStreamLevel?: string, publisherId?: string): Promise<void>;
    /**
     * Method askToAddSharingToWebConferenceSession
     * Used only on desktop application : choose which screen to share
     * FIX SIGNATURE
     * @internal
     */
    askToAddSharingToWebConferenceSession(conversation: any, conferenceSession: any, shouldAskForAudio?: boolean): void;
    /**
     * Returns WebConferenceSession if the user has an active web conference session (that he has joined)
     * @returns {WebConferenceSession} Returns WebConferenceSession or null instead
     * @internal
     * FIX SIGNATURE
     */
    getActiveWebConferenceSession(): WebConferenceSession | null;
    /**
     * Decline incoming invitation to join a web conference. This API will send update to all other connected devices to the user to notify;
     * @param bubble - The bubble to decline the web conference invitation
     * @internal
     * Returns on API call success
     */
    declineInvitationToJoinConference(bubble: Bubble): Promise<void>;
    /**
     * Removes a user from the web conference in the given bubble; This API can be used by
     * the moderators of the bubble to remove other participants too
     * @param webConferenceSession - The current web conference session
     * @param participantId - The participant ID that should be removed from the conference
     * @internal
     * @returns  Return promise
     */
    disconnectUserFromWebConference(webConferenceSession: WebConferenceSession, participantId: string): Promise<void>;
    /**
     * Add audio to an existing web conference session (ONLY IN CASE THE JOIN IS DONE VIA NOAUDIO OPTION)
     * @param webConferenceSession - the WebConferenceSession object where we want to add the media
     * @internal
     */
    addAudioToWebConferenceSession(webConferenceSession: WebConferenceSession): void;
    /**
     * API used to update the conference parameters (can be used by the conference moderator)
     * @param webConferenceSession - The Web Conference session
     * @param option - could be one of:
     * - mute  (Mutes all participants, except requester.)
     * - unmute (Unmutes all participants)
     * - lock (Disables any future participant from joining conference)
     * - unlock (Unlocks the conference)
     * @returns a promise that resolve when conference parameters are updated
     * @internal
     */
    updateConferenceParameters(webConferenceSession: WebConferenceSession, option: string): Promise<void>;
    /**
     * Method used to stop the echo test
     * @param roomDbId - the DB Id of the room where we want to get the stats
     * @internal
     */
    getConferenceTalkingTimeStats(roomDbId: string): Promise<any>;
    /**
     * Raise your hand in the concerned Conference
     * @param session - The conference session where the user is going to lower their hand
     * @returns Returns WebConferenceSession object that is related to the web conference session in that bubble
     * @internal
     */
    raiseHand(session: WebConferenceSession): Promise<WebConferenceSession>;
    /** @internal */
    putActiveConferenceOnHold(call?: any): any;
    /** @internal */
    retrieveConferenceOnHold(): any;
    /**
     * Method used to remove all incoming video sessions; Also the dynamic feed / active talker video is removed
     * @param webConferenceSession - The Web conference participant
     * @returns returns when it's done
     * @internal
     */
    removeAllRemoteVideoSessions(webConferenceSession: WebConferenceSession): void;
    /**
     * Method used to start the echo test
     * @internal
     */
    startMediaEchoTest(): Promise<void>;
    /**
     * Method used to stop the echo test
     * @internal
     */
    stopMediaEchoTest(): Promise<void>;
    /** @internal */
    hasActiveWebConferenceSession(): boolean;
    /** @internal */
    waitWebConferenceConnection(session: BubbleConference): Promise<void>;
    /**
     * Lower your hand in the concerned conference (you can also lower the hand of someone else if you are a Bubble Organizer)
     * @param session - The conference session where the user is going to lower their hand
     * @param user - The user lowering their hand
     * @returns Returns WebConferenceSession object that is related to the web conference session in that bubble
     * @internal
     */
    lowerHand(session: WebConferenceSession, user: BubbleConferenceParticipant): Promise<WebConferenceSession>;
    /** @internal */
    sendInnerEvent(name: string, data?: any): void;
    /** @internal */
    subscribeToInnerEvents(handler: any): Subscription;
    /** @internal */
    sendCustomEvent(name: string, data?: any): void;
    /** @internal */
    sendEvent(name: string, data?: any): void;
}
